//! 🔐️ Invalid consuming encoder receipts remain in their original receiving slot.
#[test]
fn native_local_original_invalid_encode_receipt_is_not_consumed(){let law:serde_json::Value=serde_json::from_str(include_str!("../../../../🛬️decode/🫴️recipient/🔁️continuation/🧫️fixtures/🔣️.json")).unwrap();let mut recipient=super::NativeEncodeRetirementRecipient::new();let receipt=super::NativeEncodeContinuation{receiving:false,maximum_bytes:law["maximumNativeBytes"].as_u64().unwrap()as usize,owned_bytes:law["initialBytes"].as_u64().unwrap()as usize,completed:law["invalidReceipt"]["completed"].as_u64().unwrap()as usize,total:law["invalidReceipt"]["total"].as_u64().unwrap()as usize,stage:0};let mut receipt=super::NativeRetirementEncodeContinuation{receipt:Some(receipt),recipient:&mut recipient};let before=receipt.owned_bytes();let mut accepted=|_|true;let error=receipt.encode(&mut accepted,|_|Ok(())).unwrap_err();assert_eq!(error.kind.as_str(),law["invalidReceipt"]["kind"].as_str().unwrap());assert_eq!(receipt.owned_bytes(),before);let(detached,_)=receipt.detach();assert_eq!(detached.owned_bytes(),before);eprintln!("[DEBUG] invalid original encode resume preserves consuming receipt in its owner slot");}
